    this.PurchaseLineExpectedDeliveryDate = this.DeliveryDate;

    if (FinTagConfiguration::isFinTagConfigurationSet(_purchLine.DataAreaId) && PurchaseOrderFinTagFeature::isEnabled())
    {
        this.FinTag = _purchLine.FinTag;
    }

    if (isConfigurationkeyEnabled(configurationKeyNum(TradeMultiShipTo)))
    {
        postalAddress = _purchLine.deliveryAddress();
    }
    else
    {
        purchTable = _purchLine.purchTable();
        postalAddress = purchTable.deliveryAddress();
    }

    this.DestState                 = postalAddress.State;
    this.DestCountryRegionId       = postalAddress.CountryRegionId;
    this.DestCounty                = postalAddress.County;

    // <GEERU>
    if (SysCountryRegionCode::isLegalEntityInCountryRegion([#isoRU]))
    {
        // M4/M7 implementation
        this.TaxItemGroup_RU           = _purchLine.TaxItemGroup;
        this.TaxGroup_RU               = _purchLine.TaxGroup;

        this.CurrencyCode_W            = _purchLine.CurrencyCode;
