    {
        vendPackingSlipTrans_Intrastat.SpecialMovement_CZ = _purchLine.purchLine_Intrastat().SpecialMovement_CZ;
        this.packVendPackingSlipTrans_Intrastat(vendPackingSlipTrans_Intrastat);
    }
    // </GEECZ>
}

