        else
        {
            select firstonly purchLine
                index hint PurchLineIdx
                where purchLine.PurchId         == _purchId
                   && purchLine.LineNumber      == _lineNumber
                   && !purchLine.IsDeleted;
        }
    }

    return purchLine;
}

